<template>
 <f7-page class="cy-main-page cy-mobile-surface cy-statistics" @page:afterin="refresh">
  <template #fixed><LedgerNavigation active="statistics" /></template>
  <header class="stat-top">
   <nav aria-label="统计周期"><button v-for="tab in periods" :key="tab.id" :aria-pressed="period === tab.id" @click="period = tab.id">{{ tab.name }}</button><button class="stat-more" aria-label="统计更多操作" @click="sheet = 'menu'">⋮</button></nav>
   <div v-if="period === 'month'" class="stat-date-strip"><button aria-label="选择年月" @click="monthDialogOpen = true">{{ month.slice(0,4) }}</button><button v-for="item in monthChoices" :key="item.value" :aria-pressed="month === item.value" @click="month = item.value">{{ item.label }}</button></div>
   <div v-else-if="period === 'year'" class="stat-date-strip"><button :aria-pressed="year === 'all'" @click="year = 'all'">所有</button><button v-for="item in yearChoices" :key="item.value" :aria-pressed="year === item.value" @click="year = item.value">{{ item.label }}</button><button @click="openYearPicker">选择年份⌄</button></div>
   <div v-else-if="period === 'custom'" class="stat-custom"><button @click="sheet = 'date'">{{ start }} — {{ end }} <span>日期设置⌄</span></button></div>
   <p v-if="monthSpanCaption" class="cy-muted" style="margin:4px 0 0">{{ monthSpanCaption }}</p>
   <TransitionGroup name="cy-reorder" tag="div" class="stat-scope-bar">
    <button key="__books" type="button" class="stat-scope-chip" :class="{ active: !!books.selectedBookIds.length }" @click="openFilters">{{ books.scopeName }} ⌄</button>
    <button v-for="chip in activeFilterChips" :key="chip.key" type="button" class="stat-scope-chip active" @click="chip.clear()">{{ chip.label }} ×</button>
    <button key="__filter" type="button" class="stat-scope-chip stat-scope-filter" @click="openFilters">筛选</button>
   </TransitionGroup>
  </header>
  <main ref="statMainEl" class="cy-page-body">
   <p v-if="error || auxiliaryError || rangeError" class="cy-message" role="alert">{{ rangeError || error || auxiliaryError }} <button @click="refresh">重试</button></p>
   <p v-if="loading" class="cy-empty" role="status">正在加载统计…</p>
   <template v-else-if="!rangeError && !error">
    <section v-if="period !== 'daily'" class="cy-panel stat-summary">
     <div class="stat-three"><f7-link v-for="key in metricKeys" :key="key" :href="detail({metric:key,type:key === 'balance' ? '' : key === 'expense' ? '3' : '2',title:metricLabels[key]+'明细'})"><span>{{ periodLabel }}{{ metricLabels[key] }}</span><strong>{{ money(totals[key],totals.complete) }}</strong></f7-link></div>
     <Transition name="cy-collapse"><div v-if="summaryExpanded"><div class="cy-collapse-inner"><div class="stat-summary-grid"><div v-for="key in metricKeys" :key="key"><span>日均{{ metricLabels[key] }}</span><strong>{{ money(new LedgerDecimal(totals[key]).div(dayCount).toString(),totals.complete) }}</strong></div></div><div v-if="auxiliaryRows.length" class="stat-summary-grid"><f7-link v-for="item in auxiliaryRows" :key="item.label" :href="item.href"><span>{{ item.label }}</span><strong>{{ money(item.value,item.complete) }}</strong></f7-link></div><p v-else class="cy-muted stat-center" style="margin-top:12px">本期无转账、借还、报销或退款记录</p></div></div></Transition>
     <button class="stat-expand" :aria-expanded="summaryExpanded" aria-label="展开收支明细汇总" @click="summaryExpanded = !summaryExpanded"><f7-icon class="stat-expand-icon" f7="chevron_down" /></button>
    </section>
    <p v-if="!totals.complete" class="cy-message">部分外币账单缺少历史汇率，相关汇总显示“—”。点入明细可查看原币金额。</p>
    <template v-for="module in visibleModules" :key="module.id">
     <section v-if="module.id === 'cash'" class="cy-panel">
      <div class="stat-heading"><h2>{{ period === 'daily' ? dailyMode === 'week' ? '本周收支' : '近七日收支' : '收支统计' }} <button class="stat-small" aria-label="放大收支图表" @click="sheet = 'chart'">⛶</button></h2><div class="stat-controls"><button v-if="period === 'daily'" class="stat-small" @click="dailyMode = dailyMode === 'week' ? 'seven' : 'week'">{{ dailyMode === 'week' ? '近七日' : '本周' }} ⇄</button><button class="stat-small" :aria-label="chartKind === 'bar' ? '切换折线图' : '切换柱状图'" @click="chartKind = chartKind === 'bar' ? 'line' : 'bar'">{{ chartKind === 'bar' ? '折线图' : '柱状图' }}</button><div v-if="period !== 'daily' && period !== 'custom'" class="cy-segments stat-segment"><button v-for="key in metricKeys" :key="key" :aria-pressed="metric === key" @click="metric = key">{{ metricLabels[key] }}</button></div></div></div>
      <StatisticsChart :option="cashOption" :height="period === 'daily' ? 220 : 235" @select="selectBucket" />
      <div v-if="period === 'daily'" class="stat-three stat-daily-summary"><div><span>支出 / 日均</span><strong class="cy-expense">{{ money(totals.expense,totals.complete) }} / {{ money(new LedgerDecimal(totals.expense).div(dayCount).toString(),totals.complete) }}</strong></div><div><span>收入 / 日均</span><strong class="cy-income">{{ money(totals.income,totals.complete) }} / {{ money(new LedgerDecimal(totals.income).div(dayCount).toString(),totals.complete) }}</strong></div></div>
      <f7-link v-if="selectedBucket" class="stat-chart-link" :href="detail({title:selectedBucket.label+'账单'},selectedBucket.from,selectedBucket.to)">{{ selectedBucket.label }} · 查看账单 ›</f7-link>
     </section>
     <section v-else-if="module.id === 'assets'" class="cy-panel"><div class="stat-heading"><h2>资产汇总</h2><f7-link href="/investments">查看详情 ›</f7-link></div><p v-if="wealthError" class="cy-muted">{{ wealthError }}</p><div class="stat-three"><div><span>净资产</span><strong>{{ assetCny(wealth?.netAssets,false) }}</strong></div><div><span>总资产</span><strong>{{ wealth && wealth.netAssets !== null ? assetCny(new LedgerDecimal(wealth.netAssets).plus(wealth.liabilities).toString(),false) : assetCny(null,false) }}</strong></div><div><span>总负债</span><strong>{{ assetCny(wealth?.liabilities,false) }}</strong></div></div><p class="cy-muted stat-footnote">全部账户 · 当前估值</p></section>
     <section v-else-if="module.id === 'budget'" class="cy-panel"><div class="stat-heading"><h2>预算占比</h2><f7-link href="/statistics/budgets">查看详情 ›</f7-link></div><p v-if="!dailyBudgets.length" class="cy-empty">还没有设置预算<br /><f7-link href="/statistics/budgets">设置本月预算 ›</f7-link></p><f7-link v-for="row in dailyBudgets" :key="row.budget.id" class="stat-budget-row" :href="`/statistics/budgets?bookId=${row.budget.bookId}`"><span>{{ bookName(row.budget.bookId) }}<small :class="{ 'cy-expense': isBudgetOver(row) }">{{ isBudgetOver(row) ? `已超支 ${ledgerMoney(new LedgerDecimal(row.remaining || '0').abs().toString(), false)}` : `剩余 ${ledgerMoney(row.remaining, false)}` }} / {{ ledgerMoney(row.available, false) }}</small></span><div class="stat-progress"><i :class="{ 'stat-over': isBudgetOver(row) }" :style="{width:budgetWidth(row)+'%'}" /></div></f7-link></section>
     <section v-else-if="module.id === 'wealth'" class="cy-panel"><WealthTrend :rows="historyRows" v-model:metric="wealthMetric" :from="range[0].unix()" :to="range[1].unix()" :time-zone="scope.timeZone" :error="wealthError" @expand="sheet = 'wealth'" /></section>
     <section v-else-if="module.id === 'heatmap' && year !== 'all'" class="cy-panel"><div class="stat-heading"><h2>收支热力</h2><div class="cy-segments stat-segment"><button v-for="key in ['expense','income'] as const" :key="key" :aria-pressed="heatMetric === key" @click="heatMetric = key">{{ metricLabels[key] }}</button></div></div><div class="stat-heatmaps"><button v-for="grid in heatmaps" :key="grid.month" type="button" class="stat-heat-month" @click="openHeatMonth(grid.month)"><h3>{{ grid.month }}月</h3><div class="stat-calendar-grid"><span v-for="i in grid.offset" :key="'blank'+i" /><i v-for="day in grid.days" :key="day.key" :style="{background:day.color}" /></div></button></div><p class="cy-muted stat-footnote">颜色越深金额越高，点任意月份放大查看每日账单</p></section>
     <section v-else-if="module.id === 'flow'" class="cy-panel"><div class="stat-heading"><h2>收支对比</h2><div class="cy-segments stat-segment"><button :aria-pressed="flowPrimary" @click="flowPrimary = true">一级分类</button><button :aria-pressed="!flowPrimary" @click="flowPrimary = false">全部</button></div></div><StatisticsChart :option="flowOption" :height="Math.max(210,Math.min(650,flowGroups.length*30))" /><p v-if="flowUnavailable" class="cy-muted">包含净退款或未知金额，请查看分类数据。</p><p v-else-if="!flowGroups.length" class="cy-empty">暂无收支数据</p></section>
     <section v-else-if="['categories','accounts','tagShare'].includes(module.id)" class="cy-panel">
      <div class="stat-heading"><h2>{{ statisticsModuleNames[module.id] }}</h2><div class="cy-segments stat-segment"><button :aria-pressed="shareMetrics[module.id] === 'expense'" @click="shareMetrics[module.id] = 'expense'">支出</button><button :aria-pressed="shareMetrics[module.id] === 'income'" @click="shareMetrics[module.id] = 'income'">收入</button></div></div>
      <div class="stat-pie"><StatisticsChart :option="pieOption(module.id)" :height="255" @select="value => selectGroup(module.id,value)" /><button class="stat-pie-center" @click="shareMetrics[module.id] = shareMetrics[module.id] === 'expense' ? 'income' : 'expense'"><span>{{ metricLabels[shareMetrics[module.id]!] }}</span><strong>{{ money(pieBreakdown(module.id).total,pieBreakdown(module.id).complete) }}</strong></button></div>
      <p v-if="!pieBreakdown(module.id).items.length" class="cy-muted stat-center">暂无数据</p><p v-else-if="!pieBreakdown(module.id).canShare" class="cy-muted">包含净退款或未知金额，不绘制占比。</p>
      <div class="stat-options"><select v-if="module.id === 'categories'" v-model="primary" aria-label="分类汇总层级"><option :value="true">一级分类</option><option :value="false">全部分类</option></select><select v-if="module.id === 'tagShare' && hasSubTags" v-model="tagMode" aria-label="标签汇总层级"><option v-for="item in tagModes" :key="item.id" :value="item.id">{{ item.label }}</option></select><label><input v-model="showAmounts[module.id]" type="checkbox" />显示金额</label></div>
      <f7-link v-for="item in pieBreakdown(module.id).items" :key="item.id" class="stat-mini-row" :href="groupLink(module.id,item)"><span>{{ item.name }}</span><strong>{{ money(item.amount,item.complete) }} <small v-if="item.percent !== null">{{ item.percent }}%</small> ›</strong></f7-link>
     </section>
     <section v-else-if="module.id === 'ranking'" class="cy-panel"><div class="stat-heading"><h2>分类数据</h2><div class="cy-segments stat-segment"><button :aria-pressed="rankMetric === 'expense'" @click="rankMetric = 'expense'">支出</button><button :aria-pressed="rankMetric === 'income'" @click="rankMetric = 'income'">收入</button></div></div><div class="stat-options"><select v-model="primary" aria-label="排名分类层级"><option :value="true">一级分类</option><option :value="false">全部分类</option></select><label v-if="period === 'month' || (period === 'year' && year !== 'all')"><input v-model="rankDetailed" type="checkbox" />同比/环比</label></div><p v-if="!ranking.items.length" class="cy-empty">暂无分类数据</p><f7-link v-for="(item,index) in ranking.items" :key="item.id" class="stat-rank" :href="detail({categoryId:item.id,primary:String(primary),type:rankMetric === 'expense' ? '3' : '2',title:item.name})"><div><i :style="{background:chartColors[index % chartColors.length]}" /><span>{{ item.name }}<small>{{ item.count }} 笔 <template v-if="item.percent !== null">· {{ item.percent }}%</template></small></span><strong>{{ money(item.amount,item.complete) }}</strong></div><div class="stat-progress"><i :style="{width:item.width+'%',background:chartColors[index % chartColors.length]}" /></div><div v-if="rankDetailed && (period === 'month' || (period === 'year' && year !== 'all'))" class="stat-comparison"><small>{{ period === 'year' ? '去年同期' : '上月同期' }} {{ comparisonText(item.id,true) }}</small><small>{{ period === 'year' ? '同比去年' : '环比上月' }} {{ comparisonText(item.id,false) }}</small></div></f7-link></section>
     <section v-else-if="module.id === 'report'" class="cy-panel"><div class="stat-heading"><h2>报表统计</h2><select v-model="reportUnit" aria-label="报表时间粒度"><option value="day">按日</option><option value="month">按月</option></select></div><div class="stat-report stat-report-head"><button v-for="column in reportColumns" :key="column.id" @click="sortReport(column.id)">{{ column.label }} {{ reportSort === column.id ? reportDescending ? '↓' : '↑' : '↕' }}</button></div><f7-link v-for="row in shownReport" :key="row.key" class="stat-report" :href="detail({title:row.key+'账单'},row.from,row.to)"><span>{{ row.key }}</span><span class="cy-income">{{ money(row.income,row.complete) }}</span><span class="cy-expense">{{ money(row.expense,row.complete) }}</span><span>{{ money(row.balance,row.complete) }}</span></f7-link><button v-if="reportRows.length > 12" class="stat-expand" @click="allReport = !allReport">{{ allReport ? '收起' : `展开全部 ${reportRows.length} 行` }}</button></section>
     <section v-else-if="module.id === 'tags'" class="cy-panel"><div class="stat-heading"><h2>标签数据</h2><select v-if="period === 'daily'" v-model="dailyTagRange" aria-label="标签统计时段"><option value="month">近一月</option><option value="week">近一周</option><option value="year">今年</option><option value="all">全部</option></select><select v-model="tagSort" aria-label="标签排序"><option value="count">按笔数</option><option value="expense">按支出</option><option value="income">按收入</option><option value="name">按名称</option></select></div><div class="stat-options"><select v-if="hasSubTags" v-model="tagMode" aria-label="标签数据层级"><option v-for="item in tagModes" :key="item.id" :value="item.id">{{ item.label }}</option></select><f7-link href="/tag/list">管理标签 ›</f7-link></div><p v-if="!tagRows.length" class="cy-empty">暂无标签数据</p><f7-link v-for="item in tagRows" :key="item.id" class="stat-tag-row" :href="detail({tagId:item.id,tagMode,title:item.name},tagRange[0].unix(),tagRange[1].unix())"><span># {{ item.name }}<small>{{ item.count }} 笔</small></span><span><small class="cy-income">收入 {{ money(item.income,item.complete) }}</small><small class="cy-expense">支出 {{ money(item.expense,item.complete) }}</small></span></f7-link></section>
     <section v-else-if="module.id === 'note' && year !== 'all'" class="cy-panel"><div class="stat-heading"><h2>{{ period === 'year' ? '全年' : '本月' }}总结</h2><button v-if="books.selectedBookIds.length <= 1" class="stat-small" @click="editNote">编辑</button></div><template v-if="books.selectedBookIds.length > 1"><p class="cy-muted">当前已多选账本，总结按单个账本或全部账本保存。</p><button class="stat-small" style="color:var(--cy-accent);margin-top:6px" @click="books.selectedBookIds = []">切到全部账本 ›</button></template><template v-else><p class="stat-note">{{ currentNote?.content || '记录这段时间的收支变化、消费心得与下期计划。' }}</p><button v-if="currentNote?.content" class="stat-small stat-note-copy" @click="copyNote">复制总结</button></template></section>
    </template>
   </template>
   <p class="cy-muted stat-center">{{ books.scopeName }} · 人民币统计</p>
  </main>
  <StatisticsMonthDialog v-model:open="monthDialogOpen" v-model="month" />
  <StatisticsSheet :open="!!sheet" :title="sheetTitle" :compact="sheet === 'menu'" :tall="sheet === 'chart' || sheet === 'wealth' || sheet === 'note' || sheet === 'analysis'" :dirty="sheetDirty" @update:open="value => { if (!value) closeSheet(); }">
   <template #action><button v-if="sheet === 'modules'" :disabled="saving" @click="saveModules">确定</button><button v-else-if="sheet === 'note'" :disabled="saving" @click="saveNote">保存</button></template>
   <p v-if="actionError" class="cy-message" role="alert">{{ actionError }} <button v-if="conflictDetected && sheet === 'note'" :disabled="saving" @click="syncNoteConflict">同步最新</button><button v-else-if="conflictDetected && sheet === 'modules'" :disabled="saving" @click="syncModulesConflict">同步最新</button></p>
   <template v-if="sheet === 'menu'"><button class="stat-menu-item" @click="openFilters">多选账本与筛选 <span>›</span></button><button class="stat-menu-item" @click="openModules">模块设置 <span>›</span></button><button class="stat-menu-item" @click="sheet = 'analysis'">消费分析 <span>›</span></button><f7-link href="/statistics/budgets" class="stat-menu-item" @click="sheet = ''">预算管理 <span>›</span></f7-link></template>
   <template v-else-if="sheet === 'filters'"><BookScope flat /><LedgerFilters flat :allow-transfer="false" /><button class="cy-button cy-primary" style="width:100%" @click="applyFilters">应用筛选</button></template>
   <template v-else-if="sheet === 'heatmapMonth' && activeHeatGrid"><div class="stat-heat-weekdays"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div><div class="stat-heat-large"><span v-for="i in activeHeatGrid.offset" :key="'lb'+i" /><f7-link v-for="day in activeHeatGrid.days" :key="day.key" :style="{background:day.color}" :href="detail({title:day.key},day.from,day.to)" @click="sheet = ''"><b>{{ day.day }}</b><small v-if="!day.complete || !new LedgerDecimal(day[heatMetric]).isZero()">{{ money(day[heatMetric],day.complete) }}</small></f7-link></div><p class="cy-muted stat-footnote">点击任意日期查看当天账单明细</p></template>
   <template v-else-if="sheet === 'date'"><div class="stat-date-form"><label v-if="period === 'month'">选择月份<input v-model="month" type="month" /></label><template v-else-if="period === 'year'"><label>输入四位年份（1970—2200）<input v-model="yearDraft" type="text" inputmode="numeric" maxlength="4" placeholder="例如 2026" /></label><p v-if="yearDraftError" class="cy-message" role="alert">{{ yearDraftError }}</p><button class="cy-button cy-primary" @click="applyYearDraft">确定</button></template><template v-else><label>起始日期<input v-model="start" type="date" /></label><label>结束日期<input v-model="end" type="date" /></label><div class="cy-actions"><button v-for="shortcut in ['本周','本月','上月','今年','去年']" :key="shortcut" class="cy-button" @click="setRange(shortcut)">{{ shortcut }}</button></div><button class="cy-button cy-primary" @click="sheet = ''">确定</button></template><button v-if="period === 'month'" class="cy-button cy-primary" @click="sheet = ''">确定</button></div></template>
   <template v-else-if="sheet === 'modules'"><p class="cy-muted">{{ periods.find(p => p.id === period)?.name }}的模块设置 · 拖动或点箭头调整顺序</p><div ref="moduleDraftListEl"><draggable v-model="moduleDraft" item-key="id" handle=".stat-drag-handle" :delay="180" :delay-on-touch-only="true" :animation="180" ghost-class="cy-drag-ghost" chosen-class="cy-drag-chosen"><template #item="{element:item,index}"><div class="stat-module-row"><span class="stat-drag-handle" aria-label="长按拖动模块">☰</span><label><input v-model="item.visible" type="checkbox" />{{ statisticsModuleNames[item.id] }}</label><button :disabled="index === 0" :aria-label="'上移'+statisticsModuleNames[item.id]" @click="moveModuleAnimated(index,index-1)">↑</button><button :disabled="index === moduleDraft.length-1" :aria-label="'下移'+statisticsModuleNames[item.id]" @click="moveModuleAnimated(index,index+1)">↓</button></div></template></draggable></div></template>
   <template v-else-if="sheet === 'chart'"><div class="cy-segments"><template v-if="period !== 'daily' && period !== 'custom'"><button v-for="key in metricKeys" :key="key" :aria-pressed="metric === key" @click="metric = key">{{ metricLabels[key] }}</button></template><button @click="chartKind = chartKind === 'bar' ? 'line' : 'bar'">{{ chartKind === 'bar' ? '切换折线图' : '切换柱状图' }}</button></div><StatisticsChart :option="cashOption" :height="380" @select="selectBucket" /><f7-link v-if="selectedBucket" :href="detail({title:selectedBucket.key},selectedBucket.from,selectedBucket.to)" @click="sheet = ''">{{ selectedBucket.key }} 查看账单 ›</f7-link></template>
   <WealthTrend v-else-if="sheet === 'wealth'" :rows="historyRows" v-model:metric="wealthMetric" :from="range[0].unix()" :to="range[1].unix()" :time-zone="scope.timeZone" :error="wealthError" expanded />
   <template v-else-if="sheet === 'note'"><p class="cy-muted">{{ books.scopeName }} · {{ notePeriod }}</p><details v-if="conflictServerNote" class="stat-note-conflict"><summary>查看已同步的最新版本</summary><p class="stat-note" style="margin-top:8px">{{ conflictServerNote }}</p></details><textarea v-model="noteDraft" class="stat-textarea" maxlength="10000" rows="14" placeholder="写下本期总结…" /></template>
   <template v-else-if="sheet === 'analysis'"><p class="cy-muted">{{ range[0].format('YYYY-MM-DD') }} 至 {{ range[1].format('YYYY-MM-DD') }} · {{ books.scopeName }}</p><pre class="stat-analysis">{{ analysisText }}</pre><div class="cy-actions"><button class="cy-button" @click="copyText(analysisText, '已复制消费分析')">复制分析</button><button class="cy-button cy-primary" @click="exportAnalysis">导出文本</button></div></template>
   <p v-if="feedback" class="cy-message" role="status">{{ feedback }}</p>
  </StatisticsSheet>
 </f7-page>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue';
import { f7 } from 'framework7-vue';
import draggable from 'vuedraggable';
import BookScope from '@/components/mobile/BookScope.vue';
import LedgerFilters from '@/components/mobile/LedgerFilters.vue';
import StatisticsChart from '@/components/mobile/StatisticsChart.vue';
import StatisticsSheet from '@/components/mobile/StatisticsSheet.vue';
import StatisticsMonthDialog from '@/components/mobile/StatisticsMonthDialog.vue';
import WealthTrend from '@/components/mobile/WealthTrend.vue';
import LedgerNavigation from '@/components/mobile/LedgerNavigation.vue';
import { useStatisticsOverview } from '@/lib/use-statistics-overview.ts';
